package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.time.*;import java.util.*;import org.json.*;
/** Plan review only. Returning a clock value neither writes nor schedules an alarm. */
public final class GoalAlarmTimeActivity extends Activity {
 static final int REQUEST=789;private Alarm alarm;private String request,error="",zone="";private GoalAlarmPlan.Snapshot plan;
 static Intent edit(Activity owner,Alarm alarm,String request){return RecordUi.intent(owner,GoalAlarmTimeActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("request",request);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);try{request=getIntent().getStringExtra("request");if(request==null||!UUID.fromString(request).toString().equals(request))throw new IllegalArgumentException();alarm=Alarm.read(new JSONObject(getIntent().getStringExtra("alarm")));if(alarm.nap!=null||alarm.napInvalid)throw new IllegalArgumentException();if(saved!=null){error=saved.getString("error","");zone=saved.getString("zone","");if(saved.containsKey("goal"))plan=new GoalAlarmPlan.Snapshot(saved.getInt("bedtime"),saved.getInt("goal"),saved.getInt("wake"),saved.getLong("revision"));}else refresh(false);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();}catch(Exception invalid){finish();}}
 private void refresh(boolean draw){try{plan=GoalAlarmPlan.load(this);zone=ZoneId.systemDefault().getId();error="";}catch(IllegalArgumentException missing){plan=null;error=missing.getMessage();}if(draw)render();}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Use sleep plan",this::finish);Design.space(body,16);if(plan!=null){GoalAlarmTime calculated=plan.time();PlanActivity.detail(body,"bed","Saved bedtime",null,Design.clock(this,plan.bedtime),null);Design.line(body);PlanActivity.detail(body,"bed","Sleep goal",null,PlanActivity.duration(plan.goal),null);Design.space(body,18);Design.text(body,Design.clock(this,calculated.minute),44,700,Design.INK).setContentDescription("Plan-derived alarm time");Design.text(body,(calculated.dayOffset==1?"Next day · ":"Same day · ")+zone,13,500,Design.MUTED);Design.space(body,16);Design.text(body,alarm.solar!=null?"Copies this time into the sunrise fallback. Your sunrise time basis stays selected.":"Copies a fixed local clock time. Later sleep plan changes do not move this alarm.",14,500,Design.BROWN);Design.space(body,14);if(alarm.date!=null){GoalAlarmTime.Dated date=calculated.on(alarm.date,ZoneId.of(zone));PlanActivity.detail(body,"calendar","Alarm date",null,date.wakeDate.toString(),null);Design.text(body,"Bedtime date: "+date.bedDate,12,400,Design.MUTED);if(date.gap||date.overlap||date.elapsed!=plan.goal){Design.space(body,8);String detail=date.gap?"This clock time is skipped; Android resolves it forward to "+Design.clock(this,date.wake.getHour()*60+date.wake.getMinute())+".":date.overlap?"This clock time occurs twice; the existing alarm uses the earlier offset.":"The clock changes during this planned interval.";Design.text(body,detail+(date.elapsed>0?" Elapsed interval: "+PlanActivity.duration((int)date.elapsed)+".":" This wall-clock plan has no positive elapsed interval on this date."),13,500,Design.BROWN);}}else Design.text(body,"Date and repeat days stay unchanged. Clock changes use the existing local-time alarm rules; elapsed time can differ from the sleep goal.",12,400,Design.MUTED);if(plan.wake!=calculated.minute){Design.space(body,10);Design.text(body,"Saved plan wake time: "+Design.clock(this,plan.wake)+". This calculation uses bedtime + goal.",12,400,Design.MUTED);}}
  if(alarm.dateInvalid)error="Choose a valid alarm date before using the sleep plan.";if(alarm.solarInvalid)error="Review Time basis before using the sleep plan.";
  if(!error.isEmpty()){Design.space(body,16);android.widget.TextView problem=Design.text(body,error,14,500,0xffa93919);problem.setContentDescription("Sleep plan alarm error");problem.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);}Design.space(body,16);Design.button(body,"Refresh saved plan",false,()->refresh(true));Design.button(body,"Open Sleep goals",false,()->startActivity(RecordUi.intent(this,PlanActivity.class)));LinearLayout footer=RecordUi.footer(body);Design.text(footer,"Review the copied draft, then Save alarm.",12,400,Design.MUTED);Design.button(footer,alarm.solar!=null?"Use as sunrise fallback":"Use fixed time",true,this::use).setEnabled(plan!=null&&!alarm.dateInvalid&&!alarm.solarInvalid);Design.button(footer,"Cancel",false,this::finish);
 }
 private void use(){try{GoalAlarmPlan.Snapshot current=GoalAlarmPlan.load(this);if(plan==null||!current.identity().equals(plan.identity())||!ZoneId.systemDefault().getId().equals(zone))throw new IllegalArgumentException("Saved plan or time zone changed. Refresh the proposal before applying it.");if(alarm.dateInvalid||alarm.solarInvalid)throw new IllegalArgumentException("Review the alarm date and Time basis first.");setResult(RESULT_OK,new Intent().putExtra("request",request).putExtra("minute",plan.time().minute).putExtra("plan",plan.identity()).putExtra("zone",zone));finish();}catch(IllegalArgumentException invalid){error=invalid.getMessage();render();}}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("error",error);out.putString("zone",zone);if(plan!=null){out.putInt("bedtime",plan.bedtime);out.putInt("goal",plan.goal);out.putInt("wake",plan.wake);out.putLong("revision",plan.revision);}}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
